        String[] t = in.nextLine().trim().split("\\s+");
        Deque<Integer> st = new ArrayDeque<>();
        for (String tok : t) {
            if (tok.equals("+") || tok.equals("-") || tok.equals("*")) {
                int b = st.pop();
                int a = st.pop();
